  const importFile = async (file: File) => {
    try {
      const parsed = parseProjectFile(await file.text())
      if (!parsed.ok) throw new Error(parsed.error)
      if (!confirm(`Nahradiť obsah projektu súborom ${file.name}? Aktuálny stav sa uloží do histórie.`)) return
      await onImport(parsed.data, file.name)
    } catch (err) {
      toast({ title: 'Import zlyhal', description: err instanceof Error ? err.message : String(err), tone: 'bad' })
    }
  }

  // AI generated by: Claude Code / claude-opus-5-5
